const removeCreditRefund = `-- name: RemoveCreditRefund :execrows
UPDATE invoices.credit_refunds
SET removed_at = $1::timestamptz, removed_by_user_id = $2::uuid, removal_reason = $3::text
WHERE id = $4 AND customer_id = $5 AND removed_at IS NULL
`

type RemoveCreditRefundParams struct {
	RemovedAt       time.Time
	RemovedByUserID uuid.UUID
	RemovalReason   string
	ID              int64
	CustomerID      int32
}

// RemoveCreditRefund is the refund's removal, once: the three columns set
// together. Its reversed movement follows in the same transaction.
func (q *Queries) RemoveCreditRefund(ctx context.Context, arg RemoveCreditRefundParams) (int64, error) {
	result, err := q.db.Exec(ctx, removeCreditRefund,
		arg.RemovedAt,
		arg.RemovedByUserID,
		arg.RemovalReason,
		arg.ID,
		arg.CustomerID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

